-- 种子数据:内置 system 账号 + 预置 CURATED 标签。
-- 单一事实源:docs/20260802224934_业务建模与接口契约.md 4.2 与 4.6。
--
-- 与 V0001 拆开的理由(backend/CLAUDE.md 第四节):一个迁移只做一件事,DDL 与数据订正分开。
-- 预置标签是**一定会变**的业务数据,焊死在建表脚本里,以后调整只能再写一个数据迁移去改,
-- 建表脚本里那份就成了永久的历史噪音。
--
-- 顺序依赖(必须保持,不可颠倒,否则第二步的外键值就是错的):
--   1. 先插入 system 账号 —— app_user 是全库唯一一张空表,GENERATED BY DEFAULT AS IDENTITY
--      的第一次插入必然拿到 id=1,这正是 app_user 表注释里“id=1 是内置 system 账号”的前提。
--   2. 再插入 CURATED 标签 —— 每一行的 created_by_user_id 都硬编码为 1,依赖第 1 步已提交。

-- ============================================================
-- 1. system 账号(id=1)
-- 刻意不持有任何 user_identity,永远登不进来;用于让 owner_user_id / created_by_user_id
-- 等归属列保持 NOT NULL —— 系统内置或导入的数据挂在一个真实存在的账号上,
-- 比把归属列做成可空、然后全链路特判要简单得多。
-- ============================================================
INSERT INTO app_user (display_name, role, status)
VALUES ('system', 'ADMIN', 'ACTIVE');

-- ============================================================
-- 2. 预置 CURATED 标签(九个,粒度按当前研发受众定,理由见文档 3.9)
-- 与 ADMIN 后续手工建的标签没有任何区别,可改可删,不设 builtin 标志位。
-- ============================================================
INSERT INTO tag (name, kind, description, sort_order, created_by_user_id) VALUES
    ('代码生成',   'CURATED', '脚手架、样板代码、接口实现',    10, 1),
    ('代码审查',   'CURATED', '评审清单、规范检查、重构建议',  20, 1),
    ('测试',       'CURATED', '用例设计、自动化测试、覆盖率',  30, 1),
    ('调试排障',   'CURATED', '日志分析、根因定位、线上问题',  40, 1),
    ('架构设计',   'CURATED', '方案设计、技术选型、拆解',      50, 1),
    ('文档',       'CURATED', '技术写作、注释、总结复盘',      60, 1),
    ('数据与 SQL', 'CURATED', '查询编写、数据分析、报表',      70, 1),
    ('部署运维',   'CURATED', '构建、发布、监控、容量',        80, 1),
    ('通用',       'CURATED', '不属于以上任何一类',            90, 1);
